package com.selton.rewasteland;

import net.minecraft.core.registries.Registries;
import net.minecraft.resources.ResourceKey;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.chunk.ChunkGenerator;
import net.minecraft.world.level.levelgen.NoiseBasedChunkGenerator;
import net.minecraft.world.level.levelgen.NoiseGeneratorSettings;

/**
 * Tells whether a level was generated by the ReWasteland world preset.
 *
 * <p>ReWasteland ships a selectable world type ({@code rewasteland:wasteland}), just like the
 * vanilla default / superflat / amplified presets. Its overworld generator uses the noise settings
 * {@code rewasteland:wasteland}; every other world type keeps vanilla noise settings. Checking the
 * generator settings is what keeps the acid systems scoped to the wasteland world: a plain world
 * generated with the same mod installed keeps vanilla water and vanilla rain.</p>
 */
public final class WastelandWorld {
    /** Noise settings id used by the {@code rewasteland:wasteland} world preset. */
    public static final ResourceKey<NoiseGeneratorSettings> NOISE_SETTINGS = ResourceKey.create(
            Registries.NOISE_SETTINGS,
            ResourceLocation.fromNamespaceAndPath(ReWasteland.MODID, "wasteland"));

    private WastelandWorld() {
    }

    /** True when the level's chunk generator uses the ReWasteland noise settings. */
    public static boolean isWasteland(ServerLevel level) {
        ChunkGenerator generator = level.getChunkSource().getGenerator();
        return generator instanceof NoiseBasedChunkGenerator noise
                && noise.generatorSettings().unwrapKey().map(NOISE_SETTINGS::equals).orElse(false);
    }
}
